#include <bits/stdc++.h>
using namespace std;
typedef long long LL;
typedef pair<int,int> pii;

const int INF = 1e9;
const int MAXN = 15;
const int MAXT = 65;

char s1[MAXN][MAXN], s2[MAXN][MAXN];
int dp[MAXN][MAXN];
int dx[4] = {-1,1,0,0};
int dy[4] = {0,0,-1,1};
int id_map[MAXT][MAXN][MAXN];
int cur_id = 1;

struct Edge {
    int u, v;
    LL cap, flow;
    Edge() {}
    Edge(int u, int v, LL cap) : u(u), v(v), cap(cap), flow(0) {}
};

struct Dinic {
    int N;
    vector<Edge> E;
    vector<vector<int>> adj;
    vector<int> dist, ptr;

    Dinic(int N) : N(N), E(), adj(N), dist(N), ptr(N) {}

    void add_edge(int u, int v, LL cap) {
        if (u == v) return;
        E.emplace_back(u, v, cap);
        adj[u].push_back((int)E.size()-1);
        E.emplace_back(v, u, 0);
        adj[v].push_back((int)E.size()-1);
    }

    bool bfs(int S, int T) {
        fill(dist.begin(), dist.end(), N+1);
        dist[S] = 0;
        queue<int> q;
        q.push(S);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == T) break;
            for (int idx : adj[u]) {
                Edge &e = E[idx];
                if (e.flow < e.cap && dist[e.v] > dist[e.u] + 1) {
                    dist[e.v] = dist[e.u] + 1;
                    q.push(e.v);
                }
            }
        }
        return dist[T] != N+1;
    }

    LL dfs(int u, int T, LL flow = -1) {
        if (u == T || flow == 0) return flow;
        for (int &i = ptr[u]; i < (int)adj[u].size(); ++i) {
            Edge &e = E[adj[u][i]];
            Edge &oe = E[adj[u][i]^1];
            if (dist[e.v] == dist[e.u] + 1) {
                LL amt = e.cap - e.flow;
                if (flow != -1 && amt > flow) amt = flow;
                LL pushed = dfs(e.v, T, amt);
                if (pushed) {
                    e.flow += pushed;
                    oe.flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    LL max_flow(int S, int T) {
        LL total = 0;
        while (bfs(S, T)) {
            fill(ptr.begin(), ptr.end(), 0);
            while (LL flow = dfs(S, T))
                total += flow;
        }
        return total;
    }
};

int main() {
    memset(dp, -1, sizeof(dp));
    int n, t;
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; ++i) scanf("%s", s1[i]+1);
    for (int time = 0; time <= t+1; ++time)
        for (int i = 1; i <= n; ++i)
            for (int j = 1; j <= n; ++j)
                id_map[time][i][j] = cur_id++;
    int source = 0, sink = cur_id;
    cur_id++;
    for (int i = 1; i <= n; ++i) scanf("%s", s2[i]+1);

    // BFS from 'Z'
    queue<pii> q;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (s1[i][j] == 'Z') {
                q.emplace(i, j);
                dp[i][j] = 0;
            }
    while (!q.empty()) {
        auto [uy, ux] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int vy = uy + dy[d], vx = ux + dx[d];
            if (vy >= 1 && vy <= n && vx >= 1 && vx <= n && s1[vy][vx] != 'Y' && dp[vy][vx] == -1) {
                dp[vy][vx] = dp[uy][ux] + 1;
                q.emplace(vy, vx);
            }
        }
    }
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (dp[i][j] == -1 || dp[i][j] > t) dp[i][j] = INF;

    Dinic dinic(cur_id);
    // source edges
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (s1[i][j] >= '1' && s1[i][j] <= '9')
                dinic.add_edge(source, id_map[0][i][j], s1[i][j]-'0');

    // time edges (precompute neighbor list)
    vector<vector<pii>> neigh(n+2, vector<pii>());
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            for (int d = 0; d < 4; ++d) {
                int vy = i + dy[d], vx = j + dx[d];
                if (vy >= 1 && vy <= n && vx >= 1 && vx <= n && s1[vy][vx] != 'Y' && s1[vy][vx] != 'Z')
                    neigh[i].emplace_back(vy, vx);
            }
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            if (s1[i][j] == 'Y' || s1[i][j] == 'Z') continue;
            for (auto [vy, vx] : neigh[i]) {
                for (int x = 0; x < t; ++x) {
                    if (dp[vy][vx] >= x+1 && dp[i][j] > x)
                        dinic.add_edge(id_map[x][i][j], id_map[x+1][vy][vx], 1000);
                }
            }
        }

    // sink edges
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            if (s1[i][j] == 'Y' || s1[i][j] == 'Z') continue;
            if (s2[i][j] >= '1' && s2[i][j] <= '9') {
                int cap = s2[i][j] - '0';
                for (int x = 0; x <= t; ++x)
                    dinic.add_edge(id_map[x][i][j], id_map[t+1][i][j], cap);
                dinic.add_edge(id_map[t+1][i][j], sink, cap);
            }
        }

    printf("%lld\n", dinic.max_flow(source, sink));
    return 0;
}
